#!/usr/bin/env python3

import re
import sys
import binascii

def hex_to_string(hex_string):
    """Convert hex string to ASCII string."""
    try:
        # Remove any non-hex characters
        clean_hex = re.sub(r'[^0-9a-fA-F]', '', hex_string)
        # Convert hex to bytes, then to string
        return binascii.unhexlify(clean_hex).decode('utf-8', errors='replace')
    except Exception as e:
        return f"[Error decoding hex: {e}]"

def extract_and_decode_hex_strings(file_path):
    """Extract and decode hex strings from the r2 script."""
    with open(file_path, 'r') as f:
        content = f.read()

    # Extract wx commands that write hex data
    wx_pattern = r'wx\s+([0-9a-fA-F]+)'
    wx_matches = re.findall(wx_pattern, content)

    print(f"Found {len(wx_matches)} hex strings in wx commands:")
    for i, hex_string in enumerate(wx_matches):
        decoded = hex_to_string(hex_string)
        print(f"{i+1}: {decoded}")

    # Look for flag patterns in decoded strings
    print("\nLooking for flag pattern 'flag{' in decoded strings:")
    for i, hex_string in enumerate(wx_matches):
        decoded = hex_to_string(hex_string)
        if 'flag{' in decoded or 'FLAG{' in decoded:
            print(f"Flag pattern found in string #{i+1}: {decoded}")

    # Extract macro definition
    macro_pattern = r'\(([^)]+)\)'
    macro_matches = re.findall(macro_pattern, content)
    if macro_matches:
        print("\nFound macro definition(s):")
        for macro in macro_matches:
            print(f"  {macro}")

    # Look for file operations that might contain flag data
    file_ops = re.findall(r'>\s*/tmp/([^\s;]+)', content)
    if file_ops:
        print("\nTemporary files created in script:")
        for file in sorted(set(file_ops)):
            print(f"  /tmp/{file}")

    # Analyze the structure at the end of the script
    hit_markers = re.findall(r'f hit(\d+) = (\d+)', content)
    if hit_markers:
        print(f"\nFound {len(hit_markers)} hit markers")
        for hit_num, offset in hit_markers[:5]:
            print(f"  hit{hit_num} at offset {offset}")
        if len(hit_markers) > 5:
            print(f"  ... and {len(hit_markers) - 5} more")

    # Look for the final command that seems to execute all hits
    final_commands = re.findall(r'\.\(([^)]+)\) @@ ([^\n]+)', content)
    if final_commands:
        print("\nFinal command(s) that execute across hit markers:")
        for macro_name, target in final_commands:
            print(f"  .({macro_name}) @@ {target}")

if __name__ == "__main__":
    if len(sys.argv) > 1:
        file_path = sys.argv[1]
    else:
        file_path = "/home/ctfplayer/ctf_files/welcome2.r2"

    extract_and_decode_hex_strings(file_path)

