def extract_flag_from_hits():
    """Extract the flag by interpreting hit values as ASCII characters"""
    with open('/home/ctfplayer/ctf_files/welcome2.r2', 'r') as f:
        content = f.read()

    # Find all hit markers
    hits = {}
    for line in content.split('\n'):
        if line.startswith('f hit'):
            parts = line.split(' = ')
            if len(parts) == 2:
                hit_num = int(parts[0].replace('f hit', ''))
                hit_val = int(parts[1])
                hits[hit_num] = hit_val

    # Sort by hit number
    sorted_hits = sorted(hits.items())

    # Convert to ASCII characters
    flag = ''
    for idx, val in sorted_hits:
        try:
            char = chr(val)
            flag += char
            print(f"hit{idx} = {val} (0x{val:02x}) -> '{char}'")
        except:
            print(f"hit{idx} = {val} (0x{val:02x}) -> Not ASCII")

    print(f"\nExtracted flag: {flag}")

    # Check if the flag looks valid
    if 'flag{' in flag or 'FLAG{' in flag:
        print("This appears to be a valid flag!")
    else:
        print("This doesn't appear to be in the expected flag format. Let's check alternatives.")

if __name__ == "__main__":
    extract_flag_from_hits()

#!/usr/bin/env python3
import re
import binascii

def decode_wx_commands():
    with open('/home/ctfplayer/ctf_files/welcome2.r2', 'r') as f:
        content = f.read()

    # Extract all wx commands
    wx_commands = []
    for line in content.split('\n'):
        if line.startswith('wx '):
            wx_commands.append(line)

    print(f"Found {len(wx_commands)} wx commands\n")

    # Decode each wx command's hex data to ASCII
    all_decoded = ""
    for i, cmd in enumerate(wx_commands):
        # Extract the hex part
        hex_part = cmd.split('wx ')[1].split(';')[0]

        try:
            # Decode hex to ASCII
            decoded = binascii.unhexlify(hex_part).decode('utf-8', errors='replace')
            all_decoded += decoded
            if i < 20:  # Just show the first 20 for brevity
                print(f"{i}: Hex: {hex_part}")
                print(f"   ASCII: {decoded}\n")
        except Exception as e:
            print(f"Error decoding {hex_part}: {e}")

    # Look for flag pattern in the combined decoded text
    print("\nSearching for flag pattern in the combined decoded text...")

    # Common flag formats
    flag_patterns = ['flag{', 'FLAG{', '{']

    for pattern in flag_patterns:
        pos = all_decoded.find(pattern)
        if pos >= 0:
            # Extract the potential flag
            start = pos
            end = all_decoded.find('}', start)
            if end >= 0:
                potential_flag = all_decoded[start:end+1]
                print(f"Potential flag: {potential_flag}")

    # If we didn't find a complete flag, look for fragments
    if 'flag{' not in all_decoded and 'FLAG{' not in all_decoded:
        print("\nLooking for flag fragments...")
        fragments = re.findall(r'[a-zA-Z0-9_{}]{5,}', all_decoded)
        for fragment in fragments:
            if '{' in fragment or '}' in fragment:
                print(f"Potential fragment: {fragment}")

    # Analyze what the script is actually doing by examining the commands
    print("\nAnalyzing the script operation...")

    # Count different command types
    cmd_types = {}
    for line in content.split('\n'):
        if line.startswith('wx '):
            cmd_types['wx'] = cmd_types.get('wx', 0) + 1
        elif line.startswith('s '):
            cmd_types['s'] = cmd_types.get('s', 0) + 1
        elif line.startswith('s+'):
            cmd_types['s+'] = cmd_types.get('s+', 0) + 1
        elif line.startswith('f '):
            cmd_types['f'] = cmd_types.get('f', 0) + 1
        elif line.startswith('.'):
            cmd_types['.'] = cmd_types.get('.', 0) + 1
        elif line.startswith('?e'):
            cmd_types['?e'] = cmd_types.get('?e', 0) + 1

    print("Command type distribution:")
    for cmd, count in cmd_types.items():
        print(f"  {cmd}: {count}")

    # Check if the script is building a string in memory
    if 'wx' in cmd_types and ('s' in cmd_types or 's+' in cmd_types):
        print("\nThe script appears to be building a string in memory.")

        # Try to follow the sequence of memory writes
        memory = {}
        current_offset = 0

        for line in content.split('\n'):
            if line.startswith('s '):
                try:
                    current_offset = int(line.split('s ')[1], 16)
                except:
                    pass
            elif line.startswith('s+'):
                try:
                    current_offset += int(line.split('s+')[1])
                except:
                    pass
            elif line.startswith('wx '):
                try:
                    hex_part = line.split('wx ')[1].split(';')[0]
                    decoded = binascii.unhexlify(hex_part)
                    for i, byte in enumerate(decoded):
                        memory[current_offset + i] = byte
                except:
                    pass

        # Convert memory to string
        memory_addresses = sorted(memory.keys())
        if memory_addresses:
            start_addr = memory_addresses[0]
            end_addr = memory_addresses[-1]

            print(f"\nReconstructed memory from {start_addr} to {end_addr} ({end_addr - start_addr + 1} bytes)")

            # Extract continuous blocks of memory
            blocks = []
            current_block = []
            last_addr = None

            for addr in memory_addresses:
                if last_addr is None or addr == last_addr + 1:
                    current_block.append(addr)
                else:
                    if current_block:
                        blocks.append(current_block)
                    current_block = [addr]
                last_addr = addr

            if current_block:
                blocks.append(current_block)

            print(f"Found {len(blocks)} continuous blocks of memory")

            # Decode each block to ASCII
            for i, block in enumerate(blocks):
                if len(block) > 16:  # Only show blocks of reasonable size
                    block_bytes = bytes([memory[addr] for addr in block])
                    try:
                        block_text = block_bytes.decode('utf-8', errors='replace')
                        print(f"\nBlock {i} ({len(block)} bytes):")
                        print(block_text)

                        # Check for flag pattern in this block
                        for pattern in flag_patterns:
                            if pattern in block_text:
                                pos = block_text.find(pattern)
                                end = block_text.find('}', pos)
                                if end >= 0:
                                    flag = block_text[pos:end+1]
                                    print(f"Found flag in block {i}: {flag}")
                    except:
                        print(f"Block {i} couldn't be decoded to ASCII")

    # Check if the script is calling another script or constructing a program
    if '.(' in content or 'pc' in content:
        print("\nThe script may be calling another script or constructing a program.")
        # Extract potential command being built
        commands = re.findall(r'\.\(([^)]+)\)', content)
        for cmd in commands:
            print(f"Script calls: {cmd}")

if __name__ == "__main__":
    decode_wx_commands()
